<?php
declare(strict_types=1);
defined('VV_ROOT') || exit;
$pages=array_filter($vv->state['contents'],fn($c)=>$c['type']==='page'&&$c['status']!=='trash');uasort($pages,fn($a,$b)=>$a['order']<=>$b['order']?:strcmp($a['id'],$b['id']));
?>
<section class="panel"><h2><?=e(t('Navigation des pages','Page navigation'))?></h2><p><?=e(t('Choisissez les pages du menu, leur ordre et un libellé dans chaque langue. Seules les pages publiques publiées sont affichées aux visiteurs.','Choose menu pages, their order and a label in each language. Only published public pages appear to visitors.'))?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="navigation.save">
<?php foreach($pages as$id=>$c):?><fieldset class="navigation-row"><legend><?=e(\VV\Content::field($c,'title'))?> · <?=e(content_status($c))?></legend><input type="hidden" name="navigation[<?=e($id)?>][version]" value="<?=(int)$c['version']?>"><label class="checkbox"><input type="checkbox" name="navigation[<?=e($id)?>][menu]" <?=$c['menu']?'checked':''?>><?=e(t('Afficher au menu','Show in menu'))?></label><div class="navigation-fields"><label><?=e(t('Ordre','Order'))?><input type="number" min="0" max="999" name="navigation[<?=e($id)?>][order]" value="<?=(int)$c['order']?>" required></label><label>FR<input name="navigation[<?=e($id)?>][label_fr]" maxlength="80" value="<?=e($c['nav_label_fr']??'')?>" placeholder="<?=e($c['title_fr'])?>"></label><label>EN<input name="navigation[<?=e($id)?>][label_en]" maxlength="80" value="<?=e($c['nav_label_en']??'')?>" placeholder="<?=e($c['title_en'])?>"></label></div><a href="<?=e(admin_url('editor',['id'=>$id]))?>"><?=e(t('Modifier la page','Edit page'))?></a></fieldset><?php endforeach;?><button class="button primary"><?=e(t('Enregistrer la navigation','Save navigation'))?></button></form></section>
